"""Keycloak client-credentials auth, Hasura GraphQL reader, and internal web client."""
from dataclasses import dataclass
import json
import logging
from pathlib import Path
import time
from typing import Any, Callable, Mapping, Sequence
import urllib.error
import urllib.parse
import urllib.request

log = logging.getLogger("dxos_agent")


@dataclass(frozen=True)
class AgentCredentials:
    """Per-cooperative Keycloak client credentials generated by `./dxos agent enable`."""

    htx_code: str
    client_id: str
    client_secret: str


def _default_urlopen(req: urllib.request.Request, timeout: float) -> Any:
    return urllib.request.urlopen(req, timeout=timeout)


def load_credentials_from_env_file(path: Path) -> AgentCredentials:
    """Load `DXOS_AGENT_*` variables from a mode-600 runtime env file."""
    values: dict[str, str] = {}
    for raw_line in path.read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, val = line.split("=", 1)
        values[key.strip()] = val.strip()

    htx_code = values.get("DXOS_AGENT_HTX", "")
    client_id = values.get("DXOS_AGENT_CLIENT_ID", "")
    client_secret = values.get("DXOS_AGENT_CLIENT_SECRET", "")
    if not htx_code or not client_id or not client_secret:
        raise ValueError(f"Incomplete agent env file: {path}")
    return AgentCredentials(htx_code=htx_code, client_id=client_id, client_secret=client_secret)


def load_all_agent_credentials(env_dir: Path) -> list[AgentCredentials]:
    """Load credentials for every cooperative enabled under *env_dir*."""
    if not env_dir.exists():
        return []
    creds: list[AgentCredentials] = []
    for path in sorted(env_dir.glob("*.env")):
        try:
            creds.append(load_credentials_from_env_file(path))
        except (OSError, ValueError):
            # Only the file name is logged: the file holds secrets, and its error text may echo them.
            log.warning("Skipping invalid agent credentials file: %s", path.name)
    return creds


class KeycloakTokenClient:
    """Fetches and caches Keycloak client_credentials bearer tokens."""

    def __init__(
        self,
        keycloak_url: str,
        credentials: AgentCredentials,
        timeout_seconds: float = 10.0,
        clock: Callable[[], float] = time.monotonic,
        urlopen_fn: Callable[[urllib.request.Request, float], Any] = _default_urlopen,
    ) -> None:
        self._token_url = f"{keycloak_url.rstrip('/')}/protocol/openid-connect/token"
        self._credentials = credentials
        self._timeout = timeout_seconds
        self._clock = clock
        self._urlopen = urlopen_fn
        self._cached_token: str | None = None
        self._expires_at: float = 0.0

    def get_token(self) -> str:
        """Return a valid bearer token, refreshing when within 30s of expiry."""
        if self._cached_token and self._expires_at - self._clock() > 30.0:
            return self._cached_token

        form = urllib.parse.urlencode(
            {
                "grant_type": "client_credentials",
                "client_id": self._credentials.client_id,
                "client_secret": self._credentials.client_secret,
            }
        ).encode("utf-8")
        req = urllib.request.Request(
            self._token_url,
            data=form,
            method="POST",
            headers={"Content-Type": "application/x-www-form-urlencoded"},
        )
        with self._urlopen(req, self._timeout) as resp:
            payload = json.loads(resp.read().decode("utf-8"))
        token = payload.get("access_token")
        if not token:
            raise RuntimeError("Keycloak token response missing access_token")
        expires_in = float(payload.get("expires_in") or 60)
        self._cached_token = str(token)
        self._expires_at = self._clock() + expires_in
        return self._cached_token


class CoreGatewayClient:
    """Calls Hasura (role `agent`) and web `/api/internal/agent/*` exclusively via APISIX."""

    def __init__(
        self,
        gateway_url: str,
        token_provider: Callable[[], str],
        timeout_seconds: float = 15.0,
        urlopen_fn: Callable[[urllib.request.Request, float], Any] = _default_urlopen,
    ) -> None:
        self._gateway_url = gateway_url.rstrip("/")
        self._token_provider = token_provider
        self._timeout = timeout_seconds
        self._urlopen = urlopen_fn

    def _request_json(
        self,
        method: str,
        path: str,
        body: Mapping[str, Any] | None = None,
        extra_headers: Mapping[str, str] | None = None,
    ) -> dict[str, Any]:
        headers = {
            "Authorization": f"Bearer {self._token_provider()}",
            "Content-Type": "application/json",
            **(extra_headers or {}),
        }
        data = json.dumps(body).encode("utf-8") if body is not None else None
        req = urllib.request.Request(f"{self._gateway_url}{path}", data=data, method=method, headers=headers)
        try:
            with self._urlopen(req, self._timeout) as resp:
                return json.loads(resp.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace") if exc.fp else str(exc)
            raise RuntimeError(f"Gateway {method} {path} failed ({exc.code}): {detail}") from exc

    def graphql(self, query: str, variables: Mapping[str, Any] | None = None) -> dict[str, Any]:
        """Execute a read-only Hasura GraphQL query as role `agent`."""
        payload: dict[str, Any] = {"query": query}
        if variables is not None:
            payload["variables"] = dict(variables)
        result = self._request_json(
            "POST",
            "/api/data/graphql",
            payload,
            extra_headers={"x-hasura-role": "agent"},
        )
        if result.get("errors"):
            raise RuntimeError(f"Hasura GraphQL error: {result['errors']}")
        return result.get("data") or {}

    def start_run(
        self,
        agent: str,
        trigger: str,
        provider: str,
        model: str,
        prompt_version: str,
        input_hash: str,
    ) -> str:
        """Register an agent run start and return its UUID."""
        res = self._request_json(
            "POST",
            "/api/internal/agent/runs",
            {
                "agent": agent,
                "trigger": trigger,
                "provider": provider,
                "model": model,
                "prompt_version": prompt_version,
                "input_hash": input_hash,
            },
        )
        return str(res["data"]["id"])

    def get_settings(self) -> dict[str, Any]:
        """Read this cooperative's agent settings (contract C1); the `data` object of the answer."""
        return dict(self._request_json("GET", "/api/internal/agent/settings").get("data") or {})

    def finish_run(
        self,
        run_id: str,
        status: str,
        tokens_in: int = 0,
        tokens_out: int = 0,
        cost_estimate_usd: float = 0.0,
        error: str | None = None,
        provider: str | None = None,
        model: str | None = None,
        external_calls: int = 0,
    ) -> None:
        """Complete an active agent run record with the provider that produced its output (contract C2)."""
        self._request_json(
            "PATCH",
            f"/api/internal/agent/runs/{run_id}",
            {
                "status": status,
                "tokens_in": tokens_in,
                "tokens_out": tokens_out,
                "cost_estimate_usd": cost_estimate_usd,
                "external_calls": external_calls,
                "provider": provider,
                "model": model,
                "error": error,
            },
        )

    def submit_proposal(self, proposal: Mapping[str, Any]) -> dict[str, Any]:
        """Submit a validated proposal to `POST /api/internal/agent/proposals`."""
        res = self._request_json("POST", "/api/internal/agent/proposals", proposal)
        return dict(res.get("data") or {})

    def post_report(self, report: Mapping[str, Any]) -> None:
        """Hand a digest report (C5 figures) to the web, which renders and queues it."""
        self._request_json("POST", "/api/internal/agent/reports", report)

    def heartbeat(self, version: str, providers: Sequence[str]) -> None:
        """Tell the web this agent is alive and which LLM providers its keys allow (contract C3)."""
        self._request_json(
            "POST",
            "/api/internal/agent/heartbeat",
            {"version": version, "providers": list(providers)},
        )
